package com.bank.settlement;

import java.math.BigDecimal;
import java.util.PriorityQueue;
import java.util.logging.*;

public class MultiBranchDemo {
    private static final Logger log = Logger.getLogger(MultiBranchDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Three branch feeds, each already sorted ascending by amount
        SettlementNode mumbai = build(new String[]{"MUM-1", "MUM-2"}, new String[]{"1000", "7000"});
        SettlementNode delhi  = build(new String[]{"DEL-1", "DEL-2"}, new String[]{"2000", "5000"});
        SettlementNode pune   = build(new String[]{"PUN-1", "PUN-2"}, new String[]{"3000", "9000"});

        log.info("Merging K=3 sorted branch feeds using a min-heap");
        MultiBranchMerger merger = new MultiBranchMerger();
        SettlementNode merged = merger.mergeK(new SettlementNode[]{mumbai, delhi, pune});

        int pos = 1;
        for (SettlementNode n = merged; n != null; n = n.next) {
            final int p = pos++;
            final SettlementNode cur = n;
            log.info(() -> "Position " + p + " -> " + cur.txnId + " amount Rs." + cur.amount);
        }
        log.info("Global sorted settlement stream produced across all branches");
    }

    private static SettlementNode build(String[] ids, String[] amounts) {
        SettlementNode dummy = new SettlementNode(null, BigDecimal.ZERO);
        SettlementNode tail = dummy;
        for (int i = 0; i < ids.length; i++) {
            tail.next = new SettlementNode(ids[i], new BigDecimal(amounts[i]));
            tail = tail.next;
        }
        return dummy.next;
    }
}

// ─── Would be in model/SettlementNode.java ───
class SettlementNode {
    String txnId;
    BigDecimal amount;
    SettlementNode next;

    SettlementNode(String txnId, BigDecimal amount) {
        this.txnId = txnId;
        this.amount = amount;
    }
}

// ─── Would be in service/MultiBranchMerger.java ───
class MultiBranchMerger {
    // Merge K sorted lists using a min-heap of size K. O(N log K) time.
    SettlementNode mergeK(SettlementNode[] lists) {
        // Min-heap ordered by amount using BigDecimal.compareTo (exact)
        PriorityQueue<SettlementNode> heap =
            new PriorityQueue<>((x, y) -> x.amount.compareTo(y.amount));

        // Seed the heap with the head of every non-empty list
        for (SettlementNode head : lists) {
            if (head != null) heap.offer(head);
        }

        SettlementNode dummy = new SettlementNode(null, BigDecimal.ZERO);
        SettlementNode tail = dummy;

        while (!heap.isEmpty()) {
            SettlementNode smallest = heap.poll();   // global minimum
            tail.next = smallest;
            tail = tail.next;
            if (smallest.next != null) {
                heap.offer(smallest.next);            // bring in the next from that list
            }
        }
        tail.next = null;  // terminate cleanly
        return dummy.next;
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
